    this.refill = refill
    this.per = per
    this.states = new Map()
  }

  advance(key, tick) {
    let st = this.states.get(key)
    if (!st) {
      st = { numer: this.capacity * this.per, lastTick: tick }
      this.states.set(key, st)
      return
    }
    const delta = tick - st.lastTick
    if (delta > 0n) {
      st.numer += this.refill * delta
      const max = this.capacity * this.per
      if (st.numer > max) st.numer = max
      st.lastTick = tick
