function validateInt(str, line, field, min) {
  if (!INT_RE.test(str)) {
    throw new ParseError(line, `${field} must be an integer of at least ${min}`)
  }
  const value = BigInt(str)
  if (value < BigInt(min)) {
    throw new ParseError(line, `${field} must be an integer of at least ${min}`)
  }
  return value
