      const refill = validateInt(refillStr, lineNumber, 'refill', 0)
      const per = validateInt(perStr, lineNumber, 'per', 1)
      policies.set(name, new Bucket(capacity, refill, per))
    } else if (directive === 'window') {
      if (eventSeen) throw new ParseError(lineNumber, 'declarations must come before the first event')
      if (rest.length !== 3) throw new ParseError(lineNumber, 'expected window <name> <limit> <span>')
